{
	"name": "opencode-notification",
	"version": "0.0.5",
	"description": "OpenCode plugin for simple system notifications when permissions are needed, generation completes, or errors occur",
	"keywords": [
		"notification",
		"opencode",
		"opencode-plugin",
		"system-notification"
	],
	"license": "Apache-2.0",
	"author": "",
	"repository": {
		"type": "git",
		"url": "git+https://github.com/IdrisGit/opencode-notification.git"
	},
	"files": [
		"dist",
		"schema"
	],
	"type": "module",
	"main": "dist/index.js",
	"module": "dist/index.js",
	"types": "dist/index.d.ts",
	"exports": {
		".": {
			"types": "./dist/index.d.ts",
			"import": "./dist/index.js"
		}
	},
	"scripts": {
		"prepack": "bun run build",
		"build": "bun run clean && bun run generate-schema && bun build index.ts --outdir dist --target bun --format esm && bunx tsc -p tsconfig.build.json --emitDeclarationOnly",
		"generate-schema": "bun scripts/generate-schema.ts",
		"clean": "rm -rf dist",
		"lint": "oxlint .",
		"fmt": "oxfmt",
		"fmt:check": "oxfmt --check"
	},
	"dependencies": {
		"@opencode-ai/plugin": "^1.2.16",
		"zod": "^4.3.6"
	},
	"devDependencies": {
		"@types/bun": "latest",
		"oxfmt": "^0.38.0",
		"oxlint": "^1.51.0",
		"typescript": "^5"
	},
	"peerDependencies": {
		"typescript": "^5"
	}
}
